class Solution {
  public long sumDigitDifferences(int[] nums) {
    int n = nums.length, digits = String.valueOf(nums[0]).length();
    long total = 0;
    for (int position = 0; position < digits; position++) {
      int[] count = new int[10];
      for (int i = 0; i < n; i++) {
        count[nums[i] % 10]++;
        nums[i] /= 10;
      }
      // pairs that differ here: all pairs minus the pairs that share the digit
      long same = 0;
      for (int c : count) same += (long) c * (c - 1) / 2;
      total += (long) n * (n - 1) / 2 - same;
    }
    return total;
  }
}
